// Batería de testeo ciego: vocabulario informal y sinónimos que no figuran literalmente en el manual
const preguntas = [
  { n: 1, pregunta: 'Si me llega roto el celu, me devuelven la guita?', seccion_esperada: '4.2 Producto con falla de fabrica' },
  { n: 2, pregunta: 'Cuanto tarda en llegar un pedido a Mendoza?', seccion_esperada: '2.1 Envios: zonas, plazos y costos (Interior / Cuyo)' },
  { n: 3, pregunta: 'Puedo pagar en 12 cuotas sin interes?', seccion_esperada: '3.1 Medios de pago (12 cuotas con 27% de recargo)' },
  { n: 4, pregunta: 'Me arrepenti de la compra y todavia no la abri, que hago?', seccion_esperada: '4.1 Derecho de arrepentimiento' },
  { n: 5, pregunta: 'Tienen local a la calle para retirar en persona?', seccion_esperada: 'No figura: debe responder No se' },
];
return preguntas.map(p => ({ json: p }));

const caso = $('Loop Over Items (1 pregunta por vez)').first().json;
const valido = j => typeof j.score === 'number' && j.document;
const topk = $('Buscar Fragmentos (Top-K = 4)').all().map(i => i.json).filter(valido);
const pasan = $input.all().map(i => i.json).filter(valido);
const titulo = t => { const m = String(t).match(/^#{1,6}\s*(.+)$/m); return (m ? m[1] : String(t)).trim().slice(0, 70); };
return [{ json: { ...caso,
  hay_fragmentos: pasan.length > 0,
  cantidad: pasan.length,
  scores_topk: topk.map(j => Math.round(j.score * 1000) / 1000),
  fragmentos: pasan.map(j => ({ titulo: titulo(j.document.pageContent), score: Math.round(j.score * 1000) / 1000,
    extracto: j.document.pageContent.replace(/\s+/g, ' ').slice(0, 220) })),
  contexto: pasan.map((j, i) => `[Fragmento ${i + 1} | score ${j.score.toFixed(2)}]\n${j.document.pageContent}`).join('\n\n---\n\n')
} }];

