const c = $('Armar Contexto RAG').first().json;
const r = $input.first().json;
const pasos = Array.isArray(r.intermediateSteps) ? r.intermediateSteps : [];
const herramientas = pasos.map(p => (p.action && p.action.tool) || p.tool || '').filter(Boolean);
return [{ json: {
  n: c.n, pregunta: c.pregunta, seccion_esperada: c.seccion_esperada,
  scores_topk: c.scores_topk, fragmentos_que_pasan_min_score: c.cantidad, fragmentos: c.fragmentos,
  ruta: c.hay_fragmentos ? 'Agente RAG' : 'No se directo (ningun fragmento supera el minimo)',
  tool_llamada: herramientas.length ? herramientas.join(', ') : 'no',
  respuesta: r.output ?? ''
} }];

// Reporte de validación: copiá este JSON completo y pegáselo a Claude
const filas = $input.all().map(i => i.json).filter(j => j.pregunta).sort((a, b) => a.n - b.n);
let parse = '';
try { parse = String($('LlamaParse · Parsear Manual').first().json.text || ''); } catch (e) {}
return [{ json: {
  modelo: 'gpt-4o-mini', embeddings: 'text-embedding-3-small', top_k: 4, min_score: 0.40, chunk_size: 1200, chunk_overlap: 150,
  parse_caracteres: parse.length,
  parse_titulos: (parse.match(/^#{1,6} /gm) || []).length,
  parse_filas_de_tabla: (parse.match(/^\|/gm) || []).length,
  parse_preview: parse.slice(0, 5000),
  resultados: filas
} }];
